"""Persistence model.

Conventions applied to every business table:

* ``id`` is a UUID generated by the application, stable across environments.
* Tenant-owned rows carry ``organization_id`` and every uniqueness constraint
  that could collide between tenants includes it.
* ``created_at`` / ``updated_at`` are UTC and set by the application, not by the
  database, so behaviour is identical on SQLite and PostgreSQL.
* Deletion is logical (``deleted_at``) for anything a user can reference from an
  estimate; audit rows are never deleted.
"""

from __future__ import annotations

import uuid
from datetime import UTC, date, datetime
from decimal import Decimal

from sqlalchemy import JSON as SAJSON
from sqlalchemy import (
    Boolean,
    CheckConstraint,
    Date,
    DateTime,
    ForeignKey,
    ForeignKeyConstraint,
    Index,
    Integer,
    String,
    Text,
    UniqueConstraint,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from .db import Amount, Base


def new_id() -> str:
    return str(uuid.uuid4())


def utcnow() -> datetime:
    return datetime.now(UTC).replace(tzinfo=None)


class TimestampMixin:
    created_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow, nullable=False)
    updated_at: Mapped[datetime] = mapped_column(
        DateTime, default=utcnow, onupdate=utcnow, nullable=False
    )


# --------------------------------------------------------------------------
# Identity, organisations, permissions
# --------------------------------------------------------------------------


class Organization(TimestampMixin, Base):
    __tablename__ = "organizations"

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    name: Mapped[str] = mapped_column(String(200), nullable=False)
    legal_name: Mapped[str | None] = mapped_column(String(200))
    company_number: Mapped[str | None] = mapped_column(String(50))
    country_code: Mapped[str] = mapped_column(String(2), nullable=False, default="BE")
    region_code: Mapped[str] = mapped_column(String(10), nullable=False, default="BE-WAL")
    locale: Mapped[str] = mapped_column(String(10), nullable=False, default="fr-BE")
    currency: Mapped[str] = mapped_column(String(3), nullable=False, default="EUR")
    timezone: Mapped[str] = mapped_column(String(50), nullable=False, default="Europe/Brussels")
    deleted_at: Mapped[datetime | None] = mapped_column(DateTime)

    settings: Mapped[OrganizationSettings] = relationship(
        back_populates="organization", uselist=False, cascade="all, delete-orphan"
    )


class OrganizationSettings(TimestampMixin, Base):
    """Company rules that drive the deterministic engine.

    These values are copied into a frozen estimate version; changing them later
    never rewrites a frozen figure.
    """

    __tablename__ = "organization_settings"

    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), primary_key=True
    )
    rounding_scale: Mapped[int] = mapped_column(Integer, nullable=False, default=2)
    rounding_mode: Mapped[str] = mapped_column(String(20), nullable=False, default="half_up")
    unit_price_scale: Mapped[int] = mapped_column(Integer, nullable=False, default=2)

    site_overheads_rate: Mapped[Decimal] = mapped_column(
        Amount, nullable=False, default=Decimal("0")
    )
    site_overheads_base: Mapped[str] = mapped_column(
        String(30), nullable=False, default="direct_cost"
    )
    general_overheads_rate: Mapped[Decimal] = mapped_column(
        Amount, nullable=False, default=Decimal("0")
    )
    general_overheads_base: Mapped[str] = mapped_column(
        String(30), nullable=False, default="direct_plus_site"
    )
    contingency_rate: Mapped[Decimal] = mapped_column(Amount, nullable=False, default=Decimal("0"))
    contingency_base: Mapped[str] = mapped_column(
        String(30), nullable=False, default="running_total"
    )
    margin_rate: Mapped[Decimal] = mapped_column(Amount, nullable=False, default=Decimal("0"))
    margin_method: Mapped[str] = mapped_column(String(20), nullable=False, default="on_cost")

    missing_price_policy: Mapped[str] = mapped_column(String(10), nullable=False, default="block")
    quote_number_pattern: Mapped[str] = mapped_column(
        String(60), nullable=False, default="DEV-{year}-{sequence:04d}"
    )
    show_internal_costs_in_client_pdf: Mapped[bool] = mapped_column(
        Boolean, nullable=False, default=False
    )
    ai_enabled: Mapped[bool] = mapped_column(Boolean, nullable=False, default=False)

    organization: Mapped[Organization] = relationship(back_populates="settings")


class TaxRateRow(TimestampMixin, Base):
    __tablename__ = "tax_rates"
    __table_args__ = (
        UniqueConstraint("organization_id", "code", "applies_from", name="uq_tax_org_code_from"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    code: Mapped[str] = mapped_column(String(30), nullable=False)
    label: Mapped[str] = mapped_column(String(120), nullable=False)
    rate: Mapped[Decimal] = mapped_column(Amount, nullable=False)
    applies_from: Mapped[datetime | None] = mapped_column(Date)
    applies_to: Mapped[datetime | None] = mapped_column(Date)
    is_default: Mapped[bool] = mapped_column(Boolean, nullable=False, default=False)
    source: Mapped[str | None] = mapped_column(String(255))


class User(TimestampMixin, Base):
    __tablename__ = "users"

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    email: Mapped[str] = mapped_column(String(255), nullable=False, unique=True)
    full_name: Mapped[str] = mapped_column(String(200), nullable=False)
    locale: Mapped[str] = mapped_column(String(10), nullable=False, default="fr-BE")
