class EstimateVersion(TimestampMixin, Base):
    """A frozen version stores the computed result *and* its inputs.

    ``snapshot`` holds the resolved lines, the price book version identifier,
    the markup policy and the tax rates that were in force. Recomputing it later
    reproduces the same numbers even if the library has moved on, which is what
    acceptance scenarios 6 and 7 require.
    """

    __tablename__ = "estimate_versions"
    __table_args__ = (
        # Frontière multi-tenant tenue par la base : l'enfant ne peut pointer
        # qu'un parent de SA propre organisation. L'action référentielle reflète
        # celle de la clé simple que double chaque composite — sans ce reflet, le
        # résultat d'une suppression dépendrait de l'ordre de création des
        # contraintes (révision `b4f2c7d81a05`).
        ForeignKeyConstraint(
            ["estimate_id", "organization_id"],
            ["estimates.id", "estimates.organization_id"],
            name="fk_estimate_versions_estimate_tenant",
            ondelete="CASCADE",
        ),
        ForeignKeyConstraint(
            ["price_book_version_id", "organization_id"],
            ["price_book_versions.id", "price_book_versions.organization_id"],
            name="fk_estimate_versions_price_book_version_tenant",
        ),
        UniqueConstraint("estimate_id", "version_number", name="uq_estimateversion_number"),
        # La clé que doublent les frontières multi-tenant pointant ICI. Un devis
        # émis désigne une version ET son organisation ; sans cette unicité,
        # SQLite refuse la clé composite avec « foreign key mismatch », et
        # PostgreSQL exigerait la même chose.
        UniqueConstraint("id", "organization_id", name="uq_estimate_versions_id_organization"),
        CheckConstraint(
            "status IN ('draft','frozen','superseded')", name="ck_estimate_version_status"
        ),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    estimate_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("estimates.id", ondelete="CASCADE"), nullable=False, index=True
    )
    version_number: Mapped[int] = mapped_column(Integer, nullable=False, default=1)
    label: Mapped[str | None] = mapped_column(String(200))
    status: Mapped[str] = mapped_column(String(20), nullable=False, default="draft")
    price_book_version_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("price_book_versions.id"), nullable=False
    )
    markup: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    taxes: Mapped[list] = mapped_column(SAJSON, nullable=False, default=list)
    rounding: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    missing_price_policy: Mapped[str] = mapped_column(String(10), nullable=False, default="block")
    snapshot: Mapped[dict | None] = mapped_column(SAJSON)
    snapshot_sha256: Mapped[str | None] = mapped_column(String(64))
    #: Totaux **bruts**, non arrondis, tels que le moteur les a produits. Ce
    #: sont eux qui servent aux calculs internes et aux comparaisons ; ils ne
    #: sont pas ce que le devis imprime.
    total_selling_price_ht: Mapped[Decimal | None] = mapped_column(Amount)
    total_ttc: Mapped[Decimal | None] = mapped_column(Amount)
    #: Totaux **du document**, figés au gel : exactement les nombres que le
    #: devis remis au client porte, sous la convention « le document
    #: s'additionne » (voir `docs/ARRONDI_DES_DOCUMENTS.md`).
    #:
    #: Deux colonnes distinctes plutôt qu'une réinterprétation des précédentes :
    #: brut et imprimé ne coïncident pas, et une colonne qui aurait porté les
    #: deux sens selon la date de la ligne aurait été un piège permanent.
    #:
    #: `NULL` a un sens précis et unique : *le total documentaire de cette
    #: version gelée n'a pas pu être reconstruit*. Il n'est jamais remplacé en
    #: silence par l'arrondi du brut — un lecteur doit savoir qu'il ne dispose
    #: pas du nombre imprimé. Une version brouillon n'en porte pas non plus :
    #: son document se recalcule à la demande.
    document_total_ht: Mapped[Decimal | None] = mapped_column(Amount)
    document_total_ttc: Mapped[Decimal | None] = mapped_column(Amount)
    frozen_at: Mapped[datetime | None] = mapped_column(DateTime)
    frozen_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))
    created_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))


class IssuedQuote(TimestampMixin, Base):
    """Un devis REMIS au client : numéroté, daté, figé, et téléchargeable.

    Une version gelée est un calcul reproductible ; ce n'en est pas encore un
    document commercial. Il lui manque un numéro, une date d'émission, une
    validité, un destinataire, et un fichier que l'entreprise peut transmettre.

    Tout ce que le document imprime est recopié ici au moment de l'émission —
    l'organisation, le client, le chantier, les lignes et les totaux. C'est la
    raison d'être de cette table : modifier ensuite la fiche client, les taux
    ou l'organisation ne change pas un devis déjà remis. Le PDF n'est jamais
    reconstruit à partir des tables vivantes ; il est lu sur le volume, tel
    qu'il a été écrit, et son empreinte le prouve.

    Une version ne s'émet qu'une fois : `uq_issued_quote_version`. Corriger un
    devis remis n'est pas une modification, c'est une nouvelle version suivie
    d'une nouvelle émission — et l'ancienne reste.

    **Aucun parent ordinaire ne l'emporte.** Chantier, estimation et version
    gelée retiennent en `RESTRICT`, et non plus en `CASCADE`. Reproduit sur une
    base jetable : supprimer le chantier faisait disparaître le devis remis
    SANS un mot, et laissait son PDF sur le volume — un fichier que plus
    aucune ligne ne désignait, et un document transmis à un client dont
    l'entreprise n'avait plus trace. Trois des cinq suppressions éprouvées se
    comportaient ainsi.

    **L'organisation non plus.** Elle emportait encore ses devis — mesuré : la
    ligne partait, le journal d'audit qui en gardait trace partait avec, et le
    PDF restait sur le volume. Une destruction motivée par un effacement
    détruisait donc sa propre preuve tout en conservant le document. Depuis
    `a5b6c7d8e9fa`, `organization_id` retient en `RESTRICT` lui aussi.

    Détruire une organisation reste possible, mais par une seule porte
    nommée : `services/conservation.py` inscrit au registre ce qu'elle va
    détruire AVANT de le détruire, et cette inscription — qui survit à
    l'organisation — est ce que le déclencheur de base exige pour laisser
    passer la suppression d'un devis. Voir l'ADR 0006.
    """

    __tablename__ = "issued_quotes"
    __table_args__ = (
        ForeignKeyConstraint(
            ["project_id", "organization_id"],
            ["projects.id", "projects.organization_id"],
            name="fk_issued_quotes_project_tenant",
            ondelete="RESTRICT",
        ),
        ForeignKeyConstraint(
            ["estimate_version_id", "organization_id"],
            ["estimate_versions.id", "estimate_versions.organization_id"],
            name="fk_issued_quotes_version_tenant",
            ondelete="RESTRICT",
        ),
        ForeignKeyConstraint(
            ["client_id", "organization_id"],
            ["clients.id", "clients.organization_id"],
            name="fk_issued_quotes_client_tenant",
        ),
        UniqueConstraint("id", "organization_id", name="uq_issued_quotes_id_organization"),
        #: Le numéro est unique DANS l'organisation, et c'est la base qui le
        #: tient — le verrou de séquence n'est qu'une convention entre écrivains
        #: bien élevés.
        UniqueConstraint("organization_id", "number", name="uq_issued_quote_number"),
        UniqueConstraint("estimate_version_id", name="uq_issued_quote_version"),
        Index("ix_issued_quotes_org_project", "organization_id", "project_id"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    #: RESTRICT, et pas CASCADE : c'était la dernière porte par laquelle un
    #: devis émis disparaissait sans un mot.
    #:
    #: Mesuré avant correction, sur base jetable : un `DELETE FROM
    #: organizations` effaçait la ligne du devis, effaçait le journal d'audit
    #: qui en gardait la trace, et laissait le PDF du client sur le volume,
    #: octet pour octet. Une purge motivée par un effacement détruisait donc sa
    #: propre preuve tout en conservant le document — exactement à l'envers.
    #:
    #: La destruction d'une organisation reste possible, mais elle passe
    #: désormais par une seule porte nommée : `services/conservation.py`, qui
    #: inscrit ce qu'elle va détruire AVANT de le détruire, dans un registre
    #: qui, lui, survit à l'organisation.
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="RESTRICT"), nullable=False, index=True
    )
    project_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("projects.id", ondelete="RESTRICT"), nullable=False, index=True
    )
    estimate_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("estimates.id", ondelete="RESTRICT"), nullable=False
    )
    estimate_version_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("estimate_versions.id", ondelete="RESTRICT"), nullable=False
    )
    #: Sans action : `NO ACTION` refuse déjà, et c'est ce qu'on veut. La fiche
    #: client s'archive, elle ne se supprime pas — voir `routers/clients.py`.
    client_id: Mapped[str] = mapped_column(String(36), ForeignKey("clients.id"), nullable=False)

    #: Le numéro imprimé, rendu par le motif de l'organisation.
    number: Mapped[str] = mapped_column(String(60), nullable=False)
    #: L'année et le rang qui l'ont produit, conservés séparément : ils
    #: expliquent le numéro, et permettent d'allouer le suivant sans le
    #: réinterpréter à l'envers.
    sequence_year: Mapped[int] = mapped_column(Integer, nullable=False)
    sequence_number: Mapped[int] = mapped_column(Integer, nullable=False)

    issued_at: Mapped[datetime] = mapped_column(DateTime, nullable=False)
    valid_until: Mapped[date] = mapped_column(Date, nullable=False)
    #: Conditions et note au client, telles qu'imprimées. Configurables, jamais
    #: gravées : ce dépôt n'affirme aucune mention légale qu'il ne peut pas
    #: démontrer.
    terms: Mapped[str | None] = mapped_column(Text)

    #: Ce que le document dit, figé. Quatre instantanés distincts plutôt qu'un
    #: seul objet : on les relit séparément, et un lecteur voit tout de suite ce
    #: qui vient d'où.
    organization_snapshot: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    client_snapshot: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    project_snapshot: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    document_snapshot: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    #: La décision prise AU MOMENT de l'émission, et non relue plus tard dans
    #: les réglages : faire apparaître les coûts internes est un choix qui
    #: engage, et il se lit sur le devis lui-même.
    include_internal_costs: Mapped[bool] = mapped_column(Boolean, nullable=False, default=False)

    #: Le fichier remis, sur le même volume que les pièces de chantier.
    pdf_storage_key: Mapped[str] = mapped_column(String(500), nullable=False)
    pdf_sha256: Mapped[str] = mapped_column(String(64), nullable=False)
    pdf_byte_size: Mapped[int] = mapped_column(Integer, nullable=False)

    issued_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))


# --------------------------------------------------------------------------
# Le cycle commercial d'un devis remis
# --------------------------------------------------------------------------

#: Les canaux par lesquels un devis circule ou une réponse revient.
CANAUX_DE_DEVIS = ("public_link", "email", "phone", "meeting", "other")

#: Ce qui peut arriver à un devis remis. Rien d'autre ne s'écrit.
EVENEMENTS_DE_DEVIS = (
    "link_created",
    "link_revoked",
    "transmitted",
    "viewed",
    "accepted",
    "declined",
    "correction",
)

#: Les deux seules réponses finales. Un devis n'en porte qu'une.
DECISIONS = ("accepted", "declined")


class QuoteEvent(TimestampMixin, Base):
    """Ce qui est arrivé à un devis remis, dans l'ordre, et sans retour.

    Le devis et son PDF ne bougent pas ; son ÉTAT commercial, lui, évolue. Cet
    état n'est stocké nulle part : il se déduit de ces événements et de la date
    du jour — c'est ce qui rend « Expiré » exact à la seconde sans tâche
    planifiée, et ce qui interdit à un état enregistré de diverger de son
    histoire.

    **Rien ne se réécrit.** Une erreur de saisie interne se corrige par un
    événement de type `correction` qui DÉSIGNE l'original et porte un motif
    obligatoire ; l'original reste lisible, barré plutôt qu'effacé. Un
    déclencheur refuse `UPDATE` et `DELETE` sur cette table : la promesse
    « append-only » n'est pas une convention entre gens bien élevés.

    Deux dates, jamais une seule. `effective_at` est le moment où la chose a eu
    lieu — un accord donné au téléphone jeudi — et `recorded_at` celui où
    quelqu'un l'a écrite ici, le lundi suivant. Les confondre ferait mentir la
    chronologie sur l'un ou l'autre.
    """

    __tablename__ = "quote_events"
    __table_args__ = (
        ForeignKeyConstraint(
            ["issued_quote_id", "organization_id"],
            ["issued_quotes.id", "issued_quotes.organization_id"],
            name="fk_quote_events_quote_tenant",
            ondelete="CASCADE",
        ),
        CheckConstraint(
            "kind IN ('" + "','".join(EVENEMENTS_DE_DEVIS) + "')", name="ck_quote_event_kind"
        ),
        CheckConstraint(
            "channel IS NULL OR channel IN ('" + "','".join(CANAUX_DE_DEVIS) + "')",
            name="ck_quote_event_channel",
        ),
        #: Une correction sans motif ne corrige rien : elle efface sans dire
        #: pourquoi. Et un motif sans correction n'a personne à désigner.
        CheckConstraint(
            "(corrects_event_id IS NULL AND correction_reason IS NULL) "
            "OR (corrects_event_id IS NOT NULL AND correction_reason IS NOT NULL "
            "AND kind = 'correction')",
            name="ck_quote_event_correction",
        ),
        Index("ix_quote_events_quote", "issued_quote_id", "recorded_at"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    issued_quote_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("issued_quotes.id", ondelete="CASCADE"), nullable=False
    )
    #: L'empreinte du PDF au moment de l'événement. Recopiée plutôt que jointe :
    #: elle prouve, dans la ligne même, DE QUEL document il est question.
    pdf_sha256: Mapped[str] = mapped_column(String(64), nullable=False)

    kind: Mapped[str] = mapped_column(String(20), nullable=False)
    channel: Mapped[str | None] = mapped_column(String(20))

    #: Qui, dans l'entreprise, a provoqué l'événement. Absent quand il vient du
    #: destinataire par le lien public — et c'est le point.
    actor_user_id: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))
    actor_email: Mapped[str | None] = mapped_column(String(255))

    #: Ce que le répondant DÉCLARE de lui-même. Aucune vérification d'identité
    #: n'est faite, et l'interface le dit : ce n'est pas une signature
    #: électronique qualifiée.
    respondent_name: Mapped[str | None] = mapped_column(String(200))
    respondent_email: Mapped[str | None] = mapped_column(String(255))

    comment: Mapped[str | None] = mapped_column(Text)

    effective_at: Mapped[datetime] = mapped_column(DateTime, nullable=False)
    recorded_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)

    corrects_event_id: Mapped[str | None] = mapped_column(String(36), ForeignKey("quote_events.id"))
    correction_reason: Mapped[str | None] = mapped_column(Text)

    request_id: Mapped[str | None] = mapped_column(String(64))


class QuoteShareLink(TimestampMixin, Base):
    """Le lien par lequel un destinataire consulte un devis, sans compte.

    **Le secret n'est pas ici.** Seule son empreinte SHA-256 est stockée : une
    copie de la base ne permet pas d'ouvrir un devis. Le secret brut n'est rendu
    qu'une fois, à la création, et n'est jamais journalisé.

    Le lien porte sa propre expiration, qui ne dépasse jamais la validité du
    devis : un document périmé ne se consulte pas plus longtemps que ce que
    l'entreprise a promis. La révocation est immédiate et vaut aussi pour les
    sessions publiques déjà ouvertes — celles-ci désignent le lien, et un lien
    révoqué les invalide toutes.
    """

    __tablename__ = "quote_share_links"
    __table_args__ = (
        ForeignKeyConstraint(
            ["issued_quote_id", "organization_id"],
            ["issued_quotes.id", "issued_quotes.organization_id"],
            name="fk_quote_share_links_quote_tenant",
            ondelete="CASCADE",
        ),
        UniqueConstraint("id", "organization_id", name="uq_quote_share_links_id_organization"),
        #: L'empreinte est l'identifiant de recherche : deux liens ne peuvent
        #: pas partager la même, et la contrainte le tient.
        UniqueConstraint("secret_sha256", name="uq_quote_share_link_secret"),
        Index("ix_quote_share_links_quote", "issued_quote_id"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    issued_quote_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("issued_quotes.id", ondelete="CASCADE"), nullable=False
    )
    secret_sha256: Mapped[str] = mapped_column(String(64), nullable=False)
    expires_at: Mapped[datetime] = mapped_column(DateTime, nullable=False)
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime)
    revoked_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))
    created_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))


class QuotePublicSession(Base):
    """La session courte d'un destinataire, après échange du secret.

    Elle vit dans un cookie `HttpOnly` : le secret du lien, lui, ne survit pas
    à la première seconde de la page — il est lu dans le fragment, retiré de
    l'historique, échangé, et oublié.

    Comme le lien, seule l'empreinte du jeton est stockée. La session ne porte
    aucun droit propre : elle désigne un lien, et tout ce que le lien perd —
    révocation, expiration — elle le perd au même instant.
    """

    __tablename__ = "quote_public_sessions"
    __table_args__ = (
        ForeignKeyConstraint(
            ["share_link_id", "organization_id"],
            ["quote_share_links.id", "quote_share_links.organization_id"],
            name="fk_quote_public_sessions_link_tenant",
            ondelete="CASCADE",
        ),
        UniqueConstraint("token_sha256", name="uq_quote_public_session_token"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    share_link_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("quote_share_links.id", ondelete="CASCADE"), nullable=False
    )
    token_sha256: Mapped[str] = mapped_column(String(64), nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)
    expires_at: Mapped[datetime] = mapped_column(DateTime, nullable=False)


# --------------------------------------------------------------------------
# Audit
# --------------------------------------------------------------------------


class AuditEvent(Base):
    """Append-only journal with a per-organisation hash chain.

    ``previous_hash`` links each row to the one before it inside the same
    organisation. Deleting or editing a row breaks the chain, which
    ``/audit/verify`` detects. This is tamper-evidence, not tamper-proofing —
    stated as such in the security threat model.
    """

    __tablename__ = "audit_events"
    __table_args__ = (
        Index("ix_audit_org_occurred", "organization_id", "occurred_at"),
        UniqueConstraint("organization_id", "sequence", name="uq_audit_org_sequence"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )
    sequence: Mapped[int] = mapped_column(Integer, nullable=False)
    occurred_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)
    actor_user_id: Mapped[str | None] = mapped_column(String(36))
    actor_email: Mapped[str | None] = mapped_column(String(255))
    action: Mapped[str] = mapped_column(String(80), nullable=False)
    object_type: Mapped[str] = mapped_column(String(60), nullable=False)
    object_id: Mapped[str | None] = mapped_column(String(36))
    summary: Mapped[str] = mapped_column(Text, nullable=False)
    payload: Mapped[dict] = mapped_column(SAJSON, nullable=False, default=dict)
    request_id: Mapped[str | None] = mapped_column(String(64))
    #: Version du schéma de hash sous laquelle l'événement a été scellé. Une
    #: constante Python seule ne permettrait pas de revérifier durablement des
    #: événements créés sous plusieurs versions : la vérification lirait le code
    #: d'aujourd'hui pour juger un scellé d'hier.
    #: Renseigné explicitement par `audit.record()`. Pas de valeur par défaut :
    #: un défaut silencieux à 1 marquerait un événement scellé en v2 comme v1,
    #: et le rendrait invérifiable.
    hash_schema_version: Mapped[int] = mapped_column(Integer, nullable=False)
    previous_hash: Mapped[str | None] = mapped_column(String(64))
    hash: Mapped[str] = mapped_column(String(64), nullable=False)


#: Les états d'une purge d'organisation.
#:
#: `requested` n'autorise RIEN. C'est la correction de fond apportée après la
#: première version : une demande inscrite y ouvrait la porte, et une demande
#: abandonnée la laissait ouverte indéfiniment. Seul `executing` autorise, et
#: seulement tant que sa fenêtre court.
ETATS_DE_PURGE = ("requested", "executing", "rows_deleted", "completed", "failed")

#: Combien de temps une autorisation d'exécution reste valable.
#:
#: Assez pour détruire les lignes d'une organisation et retirer ses fichiers ;
#: trop court pour qu'une fenêtre oubliée devienne un droit permanent. La base
#: compare cette borne à sa propre horloge, elle ne fait pas confiance à
#: l'appelant.
MINUTES_D_AUTORISATION = 15

#: Pourquoi une organisation est détruite. Une liste FERMÉE, et c'est le point.
#:
#: Le champ était auparavant un texte libre de 500 caractères. Un registre
#: censé prouver une destruction sans conserver ce qu'elle a effacé ne peut pas
#: offrir une zone où l'on écrit « à la demande de M. Dupont, Terrassements
#: Untel » — la donnée personnelle rentre alors par la porte prévue pour la
#: faire sortir. Le code dit la CATÉGORIE ; la référence opaque, elle, permet
#: de retrouver le dossier ailleurs, dans un système dont ce n'est pas le rôle
#: de garantir l'effacement.
MOTIFS_DE_PURGE = (
    #: Le contrat qui liait l'entreprise à Metreo a pris fin.
    "contract_ended",
    #: Une personne concernée a demandé l'effacement.
    "subject_request",
    #: La durée de conservation décidée est échue et l'entreprise ne veut pas
    #: conserver au-delà.
    "retention_elapsed",
    #: L'organisation était un doublon d'une autre.
    "duplicate_organization",
    #: Réinitialisation du jeu de démonstration.
    "demo_reset",
    #: Organisation créée pour une recette ou un banc d'essai.
    "test_fixture",
)


class QuoteRetentionDecision(Base):
    """Une décision de conservation : la durée, ET ce qui la fonde.

    Un nombre d'années seul n'est pas une décision — c'est une opinion sans
    auteur. La première version stockait exactement cela, un `Integer` nullable
    sur les réglages de l'organisation, et rien n'obligeait quiconque à dire
    d'où il sortait. Une durée de conservation engage l'entreprise : elle vient
    d'un droit applicable, elle a une source, elle prend effet à une date, et
    quelqu'un l'a validée. Les cinq éléments tiennent ou aucun ne tient.

    **Versionnée, jamais modifiée en place.** Corriger une décision crée une
    nouvelle ligne ; l'ancienne reste lisible. C'est le mécanisme déjà retenu
    pour les packs régionaux, et pour la même raison : une purge exécutée hier
    doit rester jugeable sur la règle qui l'autorisait, pas sur celle
    d'aujourd'hui.

    **Le dépôt n'en sème aucune.** Aucune migration, aucun `seed`, aucune
    valeur par défaut n'en crée : elles viendraient d'un droit que ce dépôt ne
    détient pas. Sans décision, la destruction est refusée — et le refus
    conserve.
    """

    __tablename__ = "quote_retention_decisions"
    __table_args__ = (
        CheckConstraint("years >= 0 AND years <= 100", name="ck_retention_years_range"),
        Index("ix_retention_decisions_org", "organization_id", "effective_from"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    organization_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("organizations.id", ondelete="CASCADE"), nullable=False, index=True
    )

    #: La durée, en années calendaires.
    years: Mapped[int] = mapped_column(Integer, nullable=False)
    #: Le droit sous lequel elle est prise — `BE-WAL`, `FR`, un code de pack.
    #: Deux entreprises soumises à deux droits n'ont pas la même durée, et une
    #: durée sans juridiction ne dit pas de quoi elle parle.
    jurisdiction: Mapped[str] = mapped_column(String(10), nullable=False)
    #: D'où elle sort. Le libellé nomme un TEXTE, pas une personne.
    source_label: Mapped[str] = mapped_column(String(300), nullable=False)
    source_url: Mapped[str | None] = mapped_column(String(500))
    #: Quand la source a été consultée. Sans cette date, « la loi dit » n'est
    #: pas vérifiable : les textes changent.
    source_checked_on: Mapped[date] = mapped_column(Date, nullable=False)
    #: À partir de quand la décision s'applique.
    effective_from: Mapped[date] = mapped_column(Date, nullable=False)

    #: Qui l'a validée, et quand. Un identifiant interne, jamais un nom saisi :
    #: l'utilisateur peut disparaître, la référence reste un identifiant.
    validated_by: Mapped[str | None] = mapped_column(String(36), ForeignKey("users.id"))
    validated_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)
    note: Mapped[str | None] = mapped_column(Text)

    created_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)


class OrganizationPurge(Base):
    """Le registre des destructions d'organisation — et il leur survit.

    Trois raisons de ne PAS le rattacher à `organizations` :

    1. une purge doit laisser une trace après l'organisation, or le journal
       d'audit porte un `organization_id` en CASCADE et meurt donc avec elle ;
    2. la ligne doit rester lisible pour ACHEVER une purge interrompue : elle
       nomme les fichiers restant à retirer du volume ;
    3. un registre qui disparaît avec ce qu'il enregistre n'est pas un registre.

    D'où l'absence de clé étrangère : `organization_id` est une colonne nue.
    C'est délibéré, et c'est la seule table du dépôt dans ce cas.

    **Ce qu'elle ne contient pas**, tout aussi délibérément : aucun texte
    libre. Un identifiant technique, un code de motif pris dans une liste
    fermée, une référence opaque contrainte par la base, des empreintes et des
    chemins de stockage. Le registre prouve qu'une destruction a eu lieu et ce
    qu'elle portait ; il n'offre nulle part où réinscrire ce qu'elle a effacé.
    """

    __tablename__ = "organization_purges"
    __table_args__ = (
        CheckConstraint(
            "status IN ('requested', 'executing', 'rows_deleted', 'completed', 'failed')",
            name="ck_organization_purge_status",
        ),
        CheckConstraint(
            "reason_code IN ('contract_ended', 'subject_request', 'retention_elapsed', "
            "'duplicate_organization', 'demo_reset', 'test_fixture')",
            name="ck_organization_purge_reason",
        ),
        #: Une autorisation n'existe pas sans sa borne, et réciproquement.
        CheckConstraint(
            "(authorized_at IS NULL) = (authorized_until IS NULL)",
            name="ck_organization_purge_window",
        ),
        Index("ix_organization_purges_org", "organization_id"),
    )

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_id)
    #: Volontairement SANS ForeignKey : voir la note de classe.
    organization_id: Mapped[str] = mapped_column(String(36), nullable=False)
    status: Mapped[str] = mapped_column(String(20), nullable=False, default="requested")

    #: Qui a demandé la destruction. L'utilisateur peut lui aussi disparaître :
    #: son identifiant est donc copié, pas référencé.
    requested_by: Mapped[str | None] = mapped_column(String(36))
    requested_at: Mapped[datetime] = mapped_column(DateTime, nullable=False, default=utcnow)

    #: La fenêtre d'exécution. `NULL` tant qu'aucune n'a été ouverte, et une
    #: purge sans fenêtre ouverte n'autorise aucune suppression — c'est la
    #: condition que le déclencheur interroge, avec l'horloge de la BASE.
    authorized_at: Mapped[datetime | None] = mapped_column(DateTime)
    authorized_until: Mapped[datetime | None] = mapped_column(DateTime)
    completed_at: Mapped[datetime | None] = mapped_column(DateTime)

    #: Le motif, pris dans `MOTIFS_DE_PURGE`. Une liste fermée, pas une phrase.
    reason_code: Mapped[str] = mapped_column(String(40), nullable=False)
    #: Une référence de dossier, facultative et OPAQUE : ni espace, ni
    #: ponctuation de phrase. La contrainte n'est pas cosmétique — c'est ce qui
    #: empêche d'y écrire « demande de Jean Dupont » sans y penser.
    reference: Mapped[str | None] = mapped_column(String(120))
    #: La durée appliquée et la décision qui l'a fondée, recopiées. Recopiées
    #: et non référencées : la décision vit dans l'organisation, elle meurt
    #: avec elle, et la purge doit rester jugeable après.
    retention_years_applied: Mapped[int] = mapped_column(Integer, nullable=False)
    retention_decision_id: Mapped[str | None] = mapped_column(String(36))

    quote_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    #: Ce qu'il y avait à détruire sur le volume : une entrée par devis, avec sa
    #: clé de stockage et l'empreinte du PDF. C'est ce qui permet de terminer
    #: une purge interrompue sans redécouvrir quoi que ce soit, et de dire
    #: exactement ce qui a été détruit.
    documents: Mapped[list] = mapped_column(SAJSON, nullable=False, default=list)
    files_deleted: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    #: Ce que le volume a refusé de rendre, s'il a refusé. Vide est le cas normal.
    files_failed: Mapped[list] = mapped_column(SAJSON, nullable=False, default=list)
